INSERT INTO manifest_state_events(item_gid, from_state, to_state, at, reason) VALUES('mfi-01M0QMD3MF4HJC39RXJZ6G34VH', 'dialed_in', 'cut', '2026-08-24T23:46:55Z', 'Operator narrowing 2026-08-24: not part of Bulkhead''s exit criterion (core-seven suites); moved to 0.9.0 Cargo to let Bulkhead ship on #113/#114 alone');
