INSERT INTO manifest_state_events(item_gid, from_state, to_state, at, reason) VALUES('mfi-01M0V21JW1SCY4CQFE3WW4Z20C', 'dialed_in', 'cut', '2026-08-24T23:46:56Z', 'Operator narrowing 2026-08-24: not part of Bulkhead''s exit criterion (core-seven suites); moved to 0.9.0 Cargo to let Bulkhead ship on #113/#114 alone');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '0', '# Major Releases');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '1', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '2', 'Forward-looking planning ledger for major releases — one block per release, minimal fields, blank');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '3', 'line between blocks. Marathon plans and other forward planning cross-reference this doc for');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '4', 'target release names/dates; it is not a history of what shipped (that''s CHANGELOG.md — lessons');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '5', 'learned belong there at ship time, not duplicated here). Contract lives in PROJECT/PDDA.md ->');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '6', '"RELEASES.md — release ledger". Add new fields only when a real need shows up.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '7', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '8', '## This file is OPTIONAL (GH-381)');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '9', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '10', '**Read this before proposing an edit to it.**');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '11', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '12', '`RELEASES.md` is an *optional planning aid*. It is not a required artifact, it is not a checklist,');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '13', 'and it is **not something to keep topped up**. An empty file, a stale file, or no file at all are');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '14', 'all perfectly valid states. The tooling agrees: `pdda.sh releases` is warn-only, never blocks, and');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '15', 'skips entirely when the file is absent — *"RELEASES.md not found — nothing to check."*');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '16', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '17', '**Do not offer to fill this in, populate it, bring it up to date, or add the release you just');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '18', 'shipped.** Do not treat a sparse file as an incomplete one. If nobody is actively planning a release');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '19', 'arc right now, the correct amount of content here is whatever is already present — including');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '20', 'nothing.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '21', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '22', 'Edit it only when an operator explicitly asks for release *planning*. That is the whole trigger.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '23', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '24', '## Scope boundary — Litmus (0.2.0) vs Nightwatch (0.3.0)');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '25', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '26', 'Added 2026-08-08 after a cross-model consult (codex + agy) found the two descriptions **not');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '27', 'decidable**: a competent agent could not route a new issue between them from the prose alone, because');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '28', 'Litmus says checks must "report red" correctly while Nightwatch says hostile states must "fail');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '29', 'clearly." Both advisors independently flagged this as blocking, and the overlap is worst exactly where');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '30', 'orchestration failures emit gate-looking verdicts.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '31', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '32', '> **Litmus owns faulty decision semantics.** A named acceptance, preflight, reviewer, or pre-advance');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '33', '> check returns pass, fail, or a *reason* inconsistent with a controlled input''s observable outcome —');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '34', '> or lacks a recorded negative control.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '35', '>');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '36', '> **Nightwatch owns run lifecycle.** Dispatch, target and worktree containment, claims, durable');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '37', '> logging, interruption, and resume — **even when lifecycle code emits a misleading message.**');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '38', '>');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '39', '> **Classify by the violated invariant, not by the wording of the message.** Split an issue that');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '40', '> violates both.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '41', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '42', 'That last clause is the load-bearing one. The intuitive rule — "a lying message is Litmus" — gives the');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '43', 'wrong answer: #426 exits 6 claiming containment worked while a file leaked, but the invariant it');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '44', 'violates is run containment, so it is Nightwatch, with the assertion of its lie written as a');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '45', 'Litmus-style test. Conversely #407 reports `pre-advance-failed` when no gate ran, and that *is* a');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '46', 'Litmus defect, because the violated invariant is the verdict itself.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '47', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '48', '**A release is not its milestone.** A milestone is a backlog and grows while you work; a release needs');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '49', 'a frozen manifest and a testable exit criterion, both recorded in the blocks below. "The open issues');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '50', 'are done" is not an exit criterion, because working on a release generates more of them.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '51', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '52', '## What belongs here, on the occasions it is used');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '53', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '54', '**Major and meaningful releases only. Not every release number.**');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '55', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '56', 'A block earns its place by being worth *planning toward* — a named arc with a theme, a target date,');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '57', 'and a milestone. If the only thing you can write in `Description:` is a restatement of what changed,');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '58', 'it belongs in CHANGELOG.md and nowhere else.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '59', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '60', '`Iterations:` reserves a band of patch numbers for a release. **Reserved, deliberately not');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '61', 'enumerated** — versions inside a band ship freely and are recorded in CHANGELOG.md only. They never');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '62', 'get a block here. The band is what makes "where does 0.2.3 go?" a question with a written answer');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '63', 'instead of one resolved by adding a row.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '64', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '65', '**A version inside an existing band is already accounted for, so a new block for it is a');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '66', 'duplicate.** That is the admission rule, and it is the only one.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '67', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '68', 'Why this is written down rather than assumed: the failure mode is not a wrong entry, it is a file');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '69', 'that stays correct at every single step while turning into the wrong thing. Add `0.2.1` because it');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '70', 'shipped, add `0.2.2` for symmetry, and this becomes a **de-facto pre-CHANGELOG** — a second,');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '71', 'hand-maintained history that is guaranteed to disagree with the real one the first time someone');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '72', 'updates one and not the other. Two sources of truth for the same fact is the defect; the row count');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '73', 'is only the symptom.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '74', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '75', 'An assistant that keeps asking for this file to be filled produces exactly that outcome, one');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '76', 'helpful suggestion at a time. Hence the section above.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '77', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '78', 'When a band is exhausted, widen it or promote the next release — do not start enumerating.');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '79', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '80', '`Milestone:` is the release -> issue-set join key (GH-284 Phase 3): a GitHub MILESTONE TITLE, not a');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '81', 'URL and not a list of issues. `GH_URL:` can name only one thing, which cannot express a release''s');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '82', 'scope. Ask GitHub what is in a release instead of maintaining a list here:');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '83', '');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '84', '    gh issue list --milestone "Quicksilver" --state open --json number,title,labels');
INSERT INTO doc_lines(repo_gid, position, content) VALUES('repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '85', '');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJJHRS147J73WWGGEJ', '87', 'Iterations: 0.1.0-0.1.4');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJW4B6HWAHKW82GFGS', '99', 'Iterations: 0.2.0-0.2.4');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJW4B6HWAHKW82GFGS', '101', 'Shipped: 2026-08-14 — RC 2026-08-09 on `development` @ `263816c`, soak window 5 days, re-verified at ship on `86ba3bd5`: `bash test/litmus-release.sh --release-gate` → exit 0, 6/6 complete, 0 false completion claims. **The ship test was the release''s own exit command, not an issue-state audit.** Convention settled 2026-08-14: an exit criterion that is MET *is* the definition of done; a release is not held open by issues it never named. Falsification check on the soak window found nothing — every issue filed 08-09 → 08-14 (#485, #491, #499, #503, #504, #509, #510, #514, #518, #520, #521, #522, #523, #525, #527, #528, #533, #534, #536, #539, #540, #542, #544) either shipped inside it or left the exit command green, and the command was re-run on a `development` containing all of those fixes.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJW4B6HWAHKW82GFGS', '103', 'RC evidence: `bash test/litmus-release.sh --release-gate` → `GOALPOST MET — all 6 manifest entries complete` (6/6, 0 remaining, 0 false completion claims). Its own negative control, `--mutate-evidence`, was re-run on the same commit and reports `negative control OBSERVED in both directions (6 pass, 0 fail)` — it detects a stripped declaration, an unregistered gate (the #461 defect), and an invariant violated in either direction. Four of the six issues are CLOSED with per-criterion evidence (#407, #417, #457, #461). **Residual scope, resolved at ship (2026-08-14).** Both entries'' gates are registered, green and control-observed — which is what this release''s exit criterion measures — but each carried acceptance criteria that did not ship, and an unshipped criterion is not a reason to hold a met goalpost open. **#375 is CLOSED** (this block previously said it remained open; that was stale). **#390''s residual is now [#546](https://github.com/Claude-AI-Tools-Ventura-County/xyz-3-agents-swarm/issues/546), milestoned Meter** — Layer 4''s host free-memory floor and packet-driven per-phase overrides, deferred by the source itself at `utils/py/marathon_drive.py:1509` (verbatim: `# Layer 4 (host free-memory floor) and packet-driven per-phase overrides are Phase 2.`). Meter is the right home rather than a parking space: a host floor is a precondition checked before spending, #382 is already a Meter member and its capture doc documents this exact deferral, and #392 is the static counterpart to this runtime one. #546 is **milestone backlog, NOT admitted to Meter''s frozen manifest** — it does not make Meter''s exit command fail, so "discovery is not admission" applies. #375''s shipped three-state `unverifiable` verdict still deliberately contradicts its criteria 1 and 5, because implementing them literally took `relay-self-sufficiency.sh` from 4/0 to 0/4 on a working machine; that is recorded on the issue and is a deliberate deviation, not an omission.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJW4B6HWAHKW82GFGS', '107', 'Manifest: FROZEN 2026-08-08 — #375, #390, #407, #417, #457, #461. Six named decision gates, a fixed denominator rather than a percentage. "Every gate" was unshippable prose: `gate_inventory.py` reports 152 of 158 gates with no declared control, and retrofitting them is explicitly out of scope. Adding an entry is a RE-SCOPE, not a bugfix: a mid-release discovery joins only if it makes the exit command fail or falsifies a named invariant, has a reproducer demonstrating that, and the operator explicitly swaps out an existing entry or accepts a date slip. Discovery is not admission — #457, #460 and #461 were all filed while executing Litmus, which is what an unfrozen boundary looks like.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJNQM0474RQEYWKJKV', '115', 'Iterations: 0.3.0-0.3.4');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJNQM0474RQEYWKJKV', '117', 'Shipped: 2026-08-14 — RC 2026-08-11 on `development`, soak window 3 days, re-verified at ship on `86ba3bd5`: `bash test/nightwatch-release.sh --release-gate` → exit 0, **manifest 8/8 complete, lifecycle 5 passing / 0 failing / 0 NOT COVERED**. Half B *executes* the lifecycle cases rather than auditing them, so this is a run that killed real children and watched them recover — not a checklist. Falsification check on the soak window found nothing: the exit command was re-run on a `development` that already contains every fix landed 08-11 → 08-14, including GH-314 (the marathon transcript write-set), which is adjacent to this release''s subject and was the one worth checking. The hostile-target write-set lifecycle case still passes via `gh514-write-set-trackable.sh`. Open non-manifest issues (#514, #467, #402, #392, #391, #386) do **not** hold this release open — the exit criterion never named them, and a milestone is a backlog, not a goalpost.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJNQM0474RQEYWKJKV', '119', 'RC evidence: `bash test/nightwatch-release.sh --release-gate` → `GOALPOST MET — all 8 manifest entries complete and every lifecycle case executes green` (manifest 8/8, lifecycle 5 passing / 0 failing / 0 NOT COVERED). Its own negative control, `--mutate-evidence`, reports 34/0 and `negative control OBSERVED in both directions`. Every manifest entry carries a recorded pre-fix control under `test/baselines/`, not an assertion that one happened. **Two entries are honest about their limits and are worth reading before signing off:** #358''s Phase 2 is a *disposition* that needs a real CI failure carrying the new instrumentation, and its capture doc forbids pre-committing one — so Phase 1 shipped and Phase 2 is blocked on an observation, not on work; and #354''s membership is Phase 1 only, which was delivered by #376/#448 rather than by this release, recorded as such rather than rebuilt. **#426''s outcome inverted its own diagnosis:** a factorial control showed the leak survives with worktree isolation OFF, so teardown was exonerated and the real cause was the GH-375 auth pre-flight running with the caller''s CWD, outside containment. **Twelve open Nightwatch-milestone issues remain and gate nothing**, per this block''s own "a release is not its milestone" rule. **CI-VERIFIED 2026-08-12, and it was not before:** the goalpost was first met on macOS only, and two of the five lifecycle cases (#388, #514) were failing on every ubuntu CI run at the time the RC was recorded — their fixtures stubbed the builder but not the reviewer binary, so `marathon_drive.py`''s probe fail-fasted and the cases never executed the code they assert on. Fixed, and the gate now reports `GOALPOST MET` with `codex` absent from `PATH`, which is the CI condition reproduced locally rather than inferred. Recorded here because it is exactly the class of thing this release exists to catch: a green result that was green about the wrong environment. The general defect is #520; the control is `test/baselines/GH-520-negative-control.md`.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJNQM0474RQEYWKJKV', '120', 'Post RC update: **#358 Phase 1 is in Nightwatch. Phase 2 is deferred to the Lantern build.** Operator decision, 2026-08-11, recorded here rather than left implicit in an issue thread. Phase 1 — the lock instrumentation — shipped and is counted in the RC evidence above; the manifest below is unchanged and this release does not wait on Phase 2. Phase 2 is the *disposition*, which needs a real CI failure carrying that instrumentation, and it belongs to Lantern because what it produces is a failure that states its own reason — Lantern''s whole subject — not a lifecycle invariant. **#358 keeps its Nightwatch milestone**, because it is a frozen manifest entry counted in this block''s evidence and re-milestoning it to tidy a join key would falsify a frozen boundary. Only the scope moved.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJNQM0474RQEYWKJKV', '124', 'Manifest: FROZEN 2026-08-11 — #408, #409, #426, #388, #387, #384, #358, plus #354 Phase 1. Eight named entries, a fixed denominator rather than a percentage. The first six were moved out of Litmus on 2026-08-08 after a codex+agy consult; #387 and #384 are added at freeze time because the exit criterion above already names their cases — it requires a cap-killed child and a restarted recovery, and nothing else in the milestone supplies either. **The milestone is not the manifest.** Nightwatch''s milestone holds 18 open issues; the twelve not listed here (#376, #378, #379, #380, #382, #386, #391, #392, #402, #467, #491, and anything filed during execution) are backlog worked inside the 0.3.0-0.3.4 band, and none of them gates the release. **AMENDED 2026-08-11:** five of those — #378, #379, #380, #382, #491 — were re-milestoned to Meter (0.6.0) at the operator''s instruction, so they are no longer Nightwatch backlog at all. The manifest above is untouched and the RC evidence stands; what changed is only the non-gating remainder. #358 stays milestoned here because it is a frozen manifest entry whose Phase 1 shipped and is counted in the RC evidence above — only its *Phase 2* moved, and it moved to **Lantern**, not Meter (see the Post RC update line above). Adding an entry is a RE-SCOPE, not a bugfix, under the same admission rule Litmus used: a mid-release discovery joins only if it makes the exit command fail or falsifies a named invariant, has a reproducer demonstrating that, and the operator explicitly swaps out an existing entry or accepts a date slip. Discovery is not admission.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMJ4GE194HWHJJS2AV2', '132', 'Iterations: 0.4.0-0.4.4');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKEYXGKWR47HX3S72J', '144', 'Iterations: 0.5.0-0.5.4');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKEYXGKWR47HX3S72J', '150', 'Manifest: FROZEN at one issue on creation — #499, which supersedes and closes #494, #495, #496 and #498. Four phases, each shippable alone: relay-drive launch preflight; a gate refusal that states its real reason; a launcher whose exit code survives plus a gate-readiness check; and a change-impact reporter. Freezing at one is the whole point — these were filed as four and unified precisely to stop a single coherent change spreading across four PRs. **RE-FROZEN AT TWO on 2026-08-11 by explicit operator decision — #499, plus #358 Phase 2.** Recorded as a re-scope rather than an edit, because the admission rule below is worthless if a manifest can grow quietly: the operator named the entry and the release, which is the documented way past the rule, and this line says so with a date instead of just showing two items where there was one. It is a genuine fit, not a parking space — Phase 2 is a *disposition* that turns a lost concurrent-append record into a failure naming its own terminal lock state, which is Lantern''s subject exactly, whereas the run lifecycle it sits inside was already handled correctly (that is the Nightwatch boundary, and it is why Phase 1 belonged there and Phase 2 does not). It was briefly a Meter member the same day and moved here before either release started; Meter''s block records the move from its side. **#358 keeps its Nightwatch milestone** — it is a frozen entry counted in Nightwatch''s RC evidence, so only its scope moved, and this is the second Lantern member not enumerable by `gh issue list --milestone Lantern`. Adding a further member is a RE-SCOPE, not a bugfix, per the Litmus rule above.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKX17AQN7Q11A0YCD7', '158', 'Iterations: 0.6.0-0.6.4');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKX17AQN7Q11A0YCD7', '163', '**RE-SCOPED 2026-08-15 by explicit operator decision — Meter is now the public-repository release candidate, and the paragraph above describes what Meter *was*.** The new sentence is: **XYZ can be handed to a stranger.** An unauthenticated clone reaches a documented entry path and exercises a supported happy path with no private context, from a tree that has been sanitized and secret-scanned. The metering work was not abandoned and it was not finished — five of its seven entries moved intact to Sundown (0.8.0), where they keep their capture docs, their acceptance criteria and their evidence. Recorded here as a re-scope with a date rather than presented as a release that always meant this, because a codename that quietly changes its subject is the same defect as a manifest that quietly grows. The reason for reusing Meter rather than opening an eighth release is that the operator named it: publication is the next thing that happens to this repository, and a launch release parked behind five unrelated engineering entries would have shipped late for reasons that have nothing to do with whether a stranger can clone it.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKX17AQN7Q11A0YCD7', '164', 'Publication target — **the deliverable is a sanitized clone, not this repository.** The public artifact is a new working tree cut from `development`, stripped of runtime state and internal working documents, committed as **fresh history with a single initial commit**, and pushed to **https://github.com/HiQS-Suite/XYZ-forge** — a new repository in a different organization, named by the operator on 2026-08-15, which becomes XYZ''s permanent home. `CHANGELOG.md` is carried forward verbatim and is the public record of the project''s history — it is a *file*, so it survives a fresh-history cut intact, and carrying 2,147 commits was rejected on 2026-08-15 for a stated reason: every document removed during sanitization stays reachable in a carried history, which makes the full-history secret scan this release requires a scan of everything ever deleted rather than a scan of one tree. Fresh history makes the sanitization complete by construction. `.tick/` (161 MB of runtime event state) and `relay-system/` (32 MB of relay transcripts) do not ship. `PROJECT/` ships as an **empty PDDA scaffold** plus the Meter build documents retained deliberately as a worked example of how PDDA is used — the method travels, the backlog does not.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKX17AQN7Q11A0YCD7', '165', 'Scope boundary — Meter vs Lantern: **Lantern owns how a failure is described; Meter owns what a run consumed and what it required.** Route by asking whether the issue names a *resource or a precondition* — dollars, turns, memory, swap, a trusted directory, a green suite — or names *the wording of a verdict whose handling was already correct*. Written down because two members straddle it and the file already has one recorded case (Litmus vs Nightwatch, 2026-08-08) of two descriptions that a competent agent could not route between. **#379 is split by that rule and belongs to both:** the overloaded exit 5 is a Lantern-shaped naming defect, the budget itself is a Meter resource, and the scope boundary above says to split an issue that violates both rather than argue it into one. **#491 is the marginal call and is placed here deliberately** — the re-scoped defect is a help-text and discoverability gap, which reads Lantern, but the invariant it violates is that the harness re-spends paid turns whose results it already holds, and the issue''s evidence is a cost measurement.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKX17AQN7Q11A0YCD7', '167', 'Manifest: FROZEN 2026-08-11 on creation — #378, #379, #380, #382, #491. **RE-SCOPED TO SIX on 2026-08-12 by explicit operator decision: #509 admitted.** **RE-SCOPED TO SIX on 2026-08-14 (second decision the same day): #509 RETIRED as complete.** Its two unchecked criteria are not unfinished work — they are blocked by a LATER deliberate decision, GH-544, which retired hosted CI for the private phase. *"A push cannot cancel a running workflow_dispatch boundary run"* is now vacuously true and permanently unwitnessable: `ci.yml` carries only `workflow_dispatch:`, so no push can start a run, and you cannot control-test an interaction between two triggers when one of them no longer exists. *"A green hosted macOS full run exists for a chosen commit"* cannot be satisfied without spending the Actions minutes #509 existed to stop and #544 formally stopped. GH-544 already records that debt in its own terms and owns the re-arm trigger (the repo goes public), so keeping #509 open under Meter tracked the same gap twice while making the manifest look one item larger than it is. Phases 1-5 shipped. **RE-SCOPED TO SIX on 2026-08-14 by explicit operator decision: #551 admitted, and the target date pulled in from 2027-01-16 to 2026-09-26 in the same decision.** Recorded as a dated re-scope for the third time rather than shown as a list that has always had seven — the admission rule is worthless if a manifest can grow quietly, and it is worth as little if the third growth is the one that stops being announced. #551 is the shared root cause under nine open issues (#272, #310, #329, #365, #395, #504, #548, plus the already-closed #314/#440/#549) in which a resolver that cannot determine its answer returns a plausible default instead of refusing. It is a genuine fit on this block''s own routing question — it names a **precondition**, not a description of a failure, so it is Meter and not Lantern — and two of its nine (#380, #491) were already Meter members, which is what surfaced it: they were being worked as separate defects when they are one. **RE-SCOPED TO SEVEN on 2026-08-15 by explicit operator decision: #555 admitted.** Recorded as a dated re-scope for the fourth time. #555 is the release''s own exit criterion — the prerequisite for the other six being verifiable — so it ships first. The seven frozen manifest entries are #378, #379, #380, #382, #491, #551, and #555. **The date moved because Nightwatch shipped.** This release''s only dependency was Nightwatch (#382''s numbers needed a durable place to land), that shipped 2026-08-14, and Meter has been unblocked since — January was a date set while its blocker was still open and never revisited when the blocker cleared. Adding a further member is a RE-SCOPE, not a bugfix, under the unchanged rule below. Recorded as a re-scope with a date rather than shown as a list that has always had six, because the admission rule below is worthless if a manifest can grow quietly. It is a genuine fit, not a parking space: GH-509 is CI minute burn and route correctness — what a run costs and what it checks before spending — which is this release''s sentence almost verbatim. The operator named the entry and the release, which is the documented way past the rule. Its plan is `PROJECT/2-WORKING/GH-509-CI-MINUTE-BURN.md`, replanned the same day on the macOS-target reframe and reviewed by agy. All six are milestoned Meter, so the ledger and `gh issue list --milestone Meter` cannot drift apart. **#358 Phase 2 was a member for part of 2026-08-11 and was moved to Lantern by operator decision the same day, before any Meter work began.** Recorded rather than quietly dropped: a frozen manifest whose membership changes without a trace is not frozen, and the honest version of "we got the routing wrong for an afternoon" is a dated line, not a clean list. It was the only entry blocked on an *observation* rather than on work, and the only one with no executable half — both of which now sit in Lantern''s exit criterion, which is where the reasoning for them lives. The move is also correct on the boundary this block defines: Phase 2 produces a failure that states its own reason, which is Lantern''s subject, not a resource or a precondition. Adding an entry is a RE-SCOPE, not a bugfix, under the same admission rule Litmus and Nightwatch used: a mid-release discovery joins only if it makes the exit command fail or falsifies a named invariant, has a reproducer demonstrating that, and the operator explicitly swaps out an existing entry or accepts a date slip. Discovery is not admission. **RE-SCOPED TO TWO on 2026-08-15 by explicit operator decision — the fifth dated re-scope of this manifest, and the only one that replaces the release''s subject rather than extending it.** The seven engineering entries are dissolved. **#380 is CLOSED and shipped under the original scope**; it stays milestoned Meter as delivered work and is not a launch member — retiring a manifest does not un-ship what it produced. **#378, #379, #382, #491 and #551 move intact to Sundown (0.8.0)**, keeping their capture docs, their verbatim acceptance criteria and their milestone history; none of them was dropped, deferred without a home, or quietly closed. **#546 moves with them as Sundown backlog** — it was Meter milestone backlog and never a manifest entry, and it follows the subject it belongs to rather than the codename it happened to sit under. **The two frozen launch entries are #555 and #563.** #555 is the release''s own exit criterion, re-pointed by the paragraph above and unchanged in its role: it ships first and it arrives RED. #563 is the launch checklist authored by an external reviewer (Codex Sol High) and covers the release boundary, public onboarding and behavior, the secret and privacy review, and the legal/CI/publication sequence. Freezing at two is the Plumbline precedent (frozen at one on creation) and is deliberate: the checklist was written as one coherent cutover and splitting it across issues is exactly what that precedent exists to prevent. **Scope is CLOSED to further admission by explicit operator instruction on 2026-08-15** — no issue filed after this date joins this manifest, and the standing admission rule below is superseded for this release only, because a launch whose scope can still grow does not have a date. Anything discovered during execution is filed, milestoned Sundown or left unmilestoned, and **waived in writing per #563''s rule: a waiver names the failed criterion, the owner, the reason and the follow-up issue — silence is not a waiver.** Two known open items are covered by that rule rather than admitted: **#564** (31 unaudited suites that can reach the caller''s clone through an empty fixture path) and **#544**''s re-arm debt (hosted CI fires on nothing while the repository is private, and going public is its own documented trigger). Both bear on publication and neither is a launch member; both need a waiver or a fix before the gate is called green.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKX17AQN7Q11A0YCD7', '168', 'Manifest-Members: 555 563');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKKDB5TCEXT75BTFJY', '176', 'Iterations: 0.7.0-0.7.4');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKKDB5TCEXT75BTFJY', '178', 'Shipped: 2026-08-18 — `XYZ_BALLAST_STRANGER_RUNS=10 test/ballast-release.sh --release-gate` → exit 0, manifest 4/4 complete, stranger''s path 4/4 passing (B1 10/10 consecutive parallel runs zero failures, B2a in-band ungated warning, B2b forced-red push refusal, B3 atomic event append).');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKKDB5TCEXT75BTFJY', '183', 'Manifest: FROZEN 2026-08-16 on creation — #14, #15, #4, #10, #3. Five entries, a fixed denominator rather than a percentage. Same admission rule Litmus and Nightwatch used: a mid-release discovery joins only if it makes the exit command fail or falsifies a named invariant, has a reproducer demonstrating that, and the operator explicitly swaps out an existing entry or accepts a date slip. Discovery is not admission. **#14 and #15 SHIPPED 2026-08-17** (PR #21, PR #20; each closed with evidence — atomic-write negative control, 10/10 consecutive parallel fresh-clone runs). **#3 SHIPPED 2026-08-17**: the durable-default and path-printing halves were already landed pre-freeze (GH-430); the sole remaining gap, a recorded negative control, closed the same day (`test/baselines/GH-3-state-dir-negative-control.md`) — closed as landed, not re-scoped or swapped. **#10 CUT 2026-08-17, invoking its own pre-declared contingency**: a driven marathon attempt (builder agy, reviewer codex, round-cap 5) escalated after 5 rounds without landing — the suite count the fix would need to touch grew from the estimated ~31 to 73 with zero mechanically adopted, and the builder self-issued a scope waiver rather than flagging the blocker back to the orchestrator. This is exactly the scope-slip the freeze anticipated ("#10 is the designated cut if scope slips... #1''s clone-identity bracket already covers the same ground *detectably* in the meantime"); cut per that pre-authorized contingency rather than re-fired. Issue #10 stays open, un-closed by this cut — the underlying containment gap remains real, just descoped from Ballast. Manifest reduced from 5 to 4 entries; this is a recorded re-scope, not a silent drop.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKKDB5TCEXT75BTFJY', '184', 'Manifest-Members: 14 15 4 3');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKKDB5TCEXT75BTFJY', '185', 'Explicit non-goals, stated so they are not silently absorbed: #16 (hosted CI re-arm — tracked separately, explicitly NOT in scope, the local pre-push gate stays the only gate), #9 (tooling floor: eslint/prettier, src/ coverage, decompositions), #11 (Sundown twin retirement), #12 (tree diet), #13 (fold scaling — its body was corrected 2026-08-16: it claimed event append is already atomic temp+rename, which was never true; #14 owns making it so).');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKFFDNYP04S68XWAPF', '193', 'Iterations: 0.8.0-0.8.4');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKFFDNYP04S68XWAPF', '198', '**WIDENED 2026-08-15 by explicit operator decision — Sundown receives Meter''s five engineering entries.** The release''s sentence becomes: **the harness accounts for what it spends, checks what it requires before spending it, and stops carrying the retired Bash lane.** Said plainly rather than argued into one theme: the twin retirement and the metering work are two subjects sharing one release, and they are here together because Meter was re-pointed at publication on 2026-08-15 and these five needed a home that was not a parking space. They arrive intact — same capture docs under `PROJECT/2-WORKING/`, same verbatim acceptance criteria, same evidence — and the honest reading of the widening is that Sundown''s date is now less trustworthy than it was, because it absorbed five entries without absorbing any schedule.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKFFDNYP04S68XWAPF', '199', '**RENUMBERED 0.7.0 → 0.8.0 on 2026-08-16 by explicit operator decision, to open 0.7.0 for Ballast.** Nothing about this release changed except its version: same codename, same target date, same manifest, same milestone. The band moves with it (`0.7.0-0.7.4` → `0.8.0-0.8.4`) because a release''s iteration band is part of its identity here, not a separate fact. Recorded as a dated line rather than shown as a block that was always 0.8.0, on the same principle the manifest re-scopes above follow: a version that changes without a trace is indistinguishable from one that was misread. The `(0.7.0)` parentheticals in Meter''s re-scope paragraphs were swept to `(0.8.0)` in the same edit — they identify *which release received the transfer*, so leaving them stale would have pointed a reader at a version that no longer exists. `CHANGELOG.md`''s existing entry is **not** swept: it is the append-only record of what was decided on 2026-08-15, when Sundown was 0.7.0, and the renumber is recorded there as its own dated entry instead.');
INSERT INTO legacy_lines(release_gid, position, content) VALUES('rel-01M0BTBRMKFFDNYP04S68XWAPF', '200', 'Manifest: **#378, #379, #382, #491, #551, #28**, received from Meter 2026-08-15, plus the twin-retirement work described above, which remains unnumbered until its issues are filed. **#28** is the RELEASES.md ledger-discipline fix (parser continuation-folding + advisory bloat checks; see its capture doc for detail), added 2026-08-18 as a post-Ballast follow-up. **#546 is milestone backlog, not a manifest entry** — it followed the metering subject here and does not gate this release, under the standing rule that discovery is not admission. **Not yet frozen.** Freezing requires the twin-retirement issues to exist so the manifest is a fixed denominator rather than a list plus a promise; until then this line is a receipt for the transfer, not a contract. #380 did not move: it is CLOSED and shipped under Meter''s original scope, and stays milestoned there.');
