INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VAR6KPD0ZX6Q8WKWZR', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '32', 'GH-32 · RELEASES app: SQLite-backed release ledger, CLI-only writes, generated RELEASES.md, cross-repo UI', 'Queue / parked intake', '9', '🚧', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-32-RELEASES-APP-SQLITE.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/32', '- **GH-32 · RELEASES app: SQLite-backed release ledger, CLI-only writes, generated RELEASES.md, cross-repo UI** 🚧 **Phase 0+1 BUILT and merged 2026-08-19 (PR #34, builder GLM 5.3 per the #33 evaluation)** — schema/CLI/writer-protocol/canonical-dump/import landed (`utils/py/releases_app.py`, suite 81/0, full gate green, independently verified); the PRD survived a 4-round Codex sol-high relay review first. Still ahead: the `/releases` route migration (Phase 0 entry gate for the measured dogfood window), the Phase 2 strict flip, and the Phase 3 cockpit card. rated 70/50/65/35. → [GH-32-RELEASES-APP-SQLITE.md](PROJECT/1-INBOX/GH-32-RELEASES-APP-SQLITE.md) · [#32](https://github.com/HiQS-Suite/XYZ-forge/issues/32) · [#33](https://github.com/HiQS-Suite/XYZ-forge/issues/33)', '2026-08-19T18:55:40Z', '2026-08-24T23:36:03Z', '70', '50', '65', '35', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VACJP47XMYQQ7E37RK', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '28', 'GH-28 · RELEASES.md ledger discipline: deterministic bloat checks + per-release tracking issue', 'Queue / parked intake', '10', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-28-RELEASES-LEDGER-DISCIPLINE.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/28', '- **GH-28 · RELEASES.md ledger discipline: deterministic bloat checks + per-release tracking issue** 🆕 **queued 2026-08-18, sharpened via /consult (single-model, agy quota-failed) 2026-08-18, post-Ballast 0.7.0 follow-up** — root cause is two gaps: the discipline rubric only fires on manual `/releases clean`, and release-level notes have no home of their own. Consult caught that the original plan would''ve reversed documented "never blocks" policy and that the parser can''t see continuation-paragraph bloat at all — both fixed: checks are now permanently advisory, scoped to active/unshipped blocks, with a required parser-folding step. rated 40/35/40/55. → [GH-28-RELEASES-LEDGER-DISCIPLINE.md](PROJECT/1-INBOX/GH-28-RELEASES-LEDGER-DISCIPLINE.md) · [#28](https://github.com/HiQS-Suite/XYZ-forge/issues/28)', '2026-08-19T18:55:40Z', '2026-08-24T23:36:03Z', '40', '35', '40', '55', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VA2536KCV4JFBPF7CA', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '17', 'GH-17 · SOP for evaluating new agent harnesses and frontier models', 'Queue / parked intake', '11', '🆕', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-17-SOP-HARNESS-MODEL-EVAL.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/17', '- **GH-17 · SOP for evaluating new agent harnesses and frontier models** 🆕 **queued 2026-08-16** — establish a standardized operating procedure, checklist, and per-harness tracking issue workflow for new harness discovery, isolation, non-interactive execution, and cross-model matrix evaluation. rated 45/30/50/60. → [GH-17-SOP-HARNESS-MODEL-EVAL.md](PROJECT/1-INBOX/GH-17-SOP-HARNESS-MODEL-EVAL.md) · [#17](https://github.com/HiQS-Suite/XYZ-forge/issues/17)', '2026-08-19T18:55:40Z', '2026-08-24T23:36:03Z', '45', '30', '50', '60', NULL);
