INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VCM10Y0A1WGWRPMMFP', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '14', 'GH-14 · appendEvent writes non-atomically, so concurrent readers can observe torn event files', 'Completed', '43', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-14-ATOMIC-EVENT-APPEND.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/14', '- **GH-14 · appendEvent writes non-atomically, so concurrent readers can observe torn event files** ✅ **SHIPPED 2026-08-17 (PR #21)** — `appendEvent` writes to a `.tmp` name then `renameSync`s into place; a `.jsonl` file that exists is always complete. `test/gh14-atomic-append.sh` 6/0; negative control `test/baselines/GH-14-negative-control.md` (5/1 pre-fix). Gap: the two `test/unit/events.test.js` cases deferred from PR #7 (quarantine, empty-file skip) were not re-authored; #5 stays open on that gap. → [GH-14-ATOMIC-EVENT-APPEND.md](PROJECT/3-COMPLETED/GH-14-ATOMIC-EVENT-APPEND.md) · [#14](https://github.com/HiQS-Suite/XYZ-forge/issues/14)', '2026-08-19T18:55:40Z', '2026-08-24T23:09:38Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VCQXCBHY8XSCPV4CEB', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '15', 'GH-15 · parallel runs are unreliable in a fresh clone; the GH-528 contention retry is not honoring its contract', 'Completed', '44', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-15-PARALLEL-FRESH-CLONE-RELIABILITY.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/15', '- **GH-15 · parallel runs are unreliable in a fresh clone; the GH-528 contention retry is not honoring its contract** ✅ **SHIPPED 2026-08-17 (PR #20 + orchestrator reconciliation)** — `validate.sh`''s parallel retry gives every suite `stdin=/dev/null`, adds a completeness catch-up for suites with no result line, and a tally-integrity guard. `test/gh528-parallel-contention-retry.sh` 9/0; negative control `test/baselines/GH-15-parallel-contention-negative-control.md` (5/4 pre-fix). Ten consecutive parallel fresh-clone runs: 10/10 exit 0, zero failures, zero contention. → [GH-15-PARALLEL-FRESH-CLONE-RELIABILITY.md](PROJECT/3-COMPLETED/GH-15-PARALLEL-FRESH-CLONE-RELIABILITY.md) · [#15](https://github.com/HiQS-Suite/XYZ-forge/issues/15)', '2026-08-19T18:55:40Z', '2026-08-24T23:09:38Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DP23VDGC5DDKFA3CXYXTZB', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '3', 'GH-3 · improve-loop.sh --state-dir durability — provenance evidence must not evaporate', 'Completed', '45', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-3-IMPROVE-LOOP-STATE-DIR.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/3', '- **GH-3 · improve-loop.sh --state-dir durability — provenance evidence must not evaporate** ✅ **SHIPPED 2026-08-17 (closed as landed)** — durable default and path-printing were already landed pre-Ballast (GH-430); the sole remaining gap, a recorded negative control, closed 2026-08-17 (`test/baselines/GH-3-state-dir-negative-control.md`, 6/2 pre-fix → 8/0 post-fix). → [GH-3-IMPROVE-LOOP-STATE-DIR.md](PROJECT/3-COMPLETED/GH-3-IMPROVE-LOOP-STATE-DIR.md) · [#3](https://github.com/HiQS-Suite/XYZ-forge/issues/3)', '2026-08-19T18:55:40Z', '2026-08-24T23:09:38Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DQ00PCDP50DH1TFMSE4AV4', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '67', 'GH-67 · Commandcode builder default widened to `--yolo` — closer evaluation → possible build', 'Queue / parked intake', '8', '🆕', NULL, NULL, NULL, NULL, 'https://github.com/HiQS-Suite/XYZ-forge/issues/67', '- **GH-67 · Commandcode builder default widened to `--yolo` — closer evaluation → possible build** 🆕 **queued 2026-08-19 as the NEXT immediate item (operator call, session close)** — PR #60 moved the default from the bounded `--permission-mode auto-accept` to `--yolo` (alias for `--dangerously-skip-permissions`), unmentioned in a fuzzing PR. Evaluate whether the turn shim’s containment (worktree isolation, `ALLOW_PATHS`, commit-bypass guard) genuinely makes the child CLI’s permission mode irrelevant; if yes, RATIFY — write the containment argument down in AGENTS.md/the shim docs and pin it — if no, revert the default and drop the `--yolo` test pin. Sibling check either way: `claude-turn.py` uses `--permission-mode acceptEdits`; confirm the two adapters differ on purpose. rated 88/80/45/70 ovr 340. → [#67](https://github.com/HiQS-Suite/XYZ-forge/issues/67)', '2026-08-19T19:12:00Z', '2026-08-24T23:36:03Z', '88', '80', '45', '70', '340');
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DZZGNQVK65X0Y63AYGCM4E', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '75', 'GH-75 · single-page HTML dashboard: releases (mid/long term) + roadmap (immediate) in one read-only view', 'Queue / parked intake', '6', '🆕', NULL, NULL, NULL, NULL, 'https://github.com/HiQS-Suite/XYZ-forge/issues/75', '- **GH-75 · single-page HTML dashboard: releases (mid/long term) + roadmap (immediate) in one read-only view** 🆕 **queued 2026-08-19 at the FRONT of the line (operator call)** — a `releases dashboard` verb renders one self-contained HTML file from `releases.db`, with a card per release (version, codename, status, target, days-to-target, manifest open/closed split, exit criterion) and a card per `roadmap_items` row grouped by section in ledger order, plus a header strip carrying generation, receipt count, and a stale-sync banner when `ROADMAP.md` is ahead of the shadow. Read-only by construction: no writer lock, no generation bump, no receipt — safe to run mid-merge. First real consumer of the GH-69 shadow rows. rated 90/40/85/55. → [#75](https://github.com/HiQS-Suite/XYZ-forge/issues/75)', '2026-08-19T21:49:01Z', '2026-08-24T23:36:03Z', '90', '40', '85', '55', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0DZZGNRVEH9GPW7J3VPBP4B', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '61', 'GH-61 · RELEASES ledger durability hardening (GH-57 follow-up)', 'Queue / parked intake', '7', '🆕', NULL, NULL, NULL, NULL, 'https://github.com/HiQS-Suite/XYZ-forge/issues/62', '- **GH-61 · RELEASES ledger durability hardening (GH-57 follow-up)** 🆕 **queued 2026-08-19 — filed 2026-08-19 out of the PR #60 review and un-triaged until now** — four scoped test follow-ups under one parent: exact ledger state asserted after crash recovery ([#62](https://github.com/HiQS-Suite/XYZ-forge/issues/62)), writer-lock stress and owner-death recovery ([#63](https://github.com/HiQS-Suite/XYZ-forge/issues/63)), seeded malformed-dump property coverage ([#64](https://github.com/HiQS-Suite/XYZ-forge/issues/64)), and a portable artifact-hash helper ([#65](https://github.com/HiQS-Suite/XYZ-forge/issues/65)). rated 45/55/40/50. → [#61](https://github.com/HiQS-Suite/XYZ-forge/issues/61)', '2026-08-19T21:49:01Z', '2026-08-24T23:36:03Z', '45', '55', '40', '50', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0E5Z0TP7WTZFKS6SQYW17KK', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '77', 'GH-77 · `/standup` — session-scoped triage: what did I leave open, what is rotting, is the plan still right?', 'Completed', '22', '✅', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-77-STANDUP-SESSION-TRIAGE.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/77', '- **GH-77 · `/standup` — session-scoped triage: what did I leave open, what is rotting, is the plan still right?** ✅ **CLOSED 2026-08-22 (issue closed; ledger reconciled)** — the instrument the operator reaches for constantly, and the answer to the confidence problem the 2026-08-19 audit exposed: a shipped release left `active` for a day, four ledger markers contradicting GitHub, five issues filed into no index — all discoverable in seconds, none discovered by anything. Session + local state only (no history sweep; `/radar` keeps that job), park-only write authority, both halves every run, tactical list hard-capped at 7 items and the strategic read at ~5 lines. Carries an interface catalogue for the RELEASES CLI, the ROADMAP entry schema, PDDA lifecycle, and the one-marathon rail, so every recommendation names the exact command that closes it. rated 95/70/85/30. → [GH-77-STANDUP-SESSION-TRIAGE.md](PROJECT/1-INBOX/GH-77-STANDUP-SESSION-TRIAGE.md) · [#77](https://github.com/HiQS-Suite/XYZ-forge/issues/77) · [GH-77-STANDUP-SESSION-TRIAGE.md](PROJECT/2-WORKING/GH-77-STANDUP-SESSION-TRIAGE.md)', '2026-08-19T23:33:36Z', '2026-08-24T23:09:38Z', '95', '70', '85', '30', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0EWSZJX1WYGDFBNMS2TJFT0', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '94', 'GH-94 · research: programmatic tool calling & code-mode execution for harnesses, telemetry, and containment', 'Completed', '37', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-94-PROGRAMMATIC-TOOL-CALLING.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/94', '- **GH-94 · research: programmatic tool calling & code-mode execution for harnesses, telemetry, and containment** ✅ **SHIPPED 2026-08-20 (PR #100; issue closed)** — implemented `utils/py/script_runner.py` with AST serialization normalization, PGID process-group session management (`setsid`), and fail-closed macOS seatbelt sandboxing (`sandbox-exec`); instrumented `utils/ate/scripts/run_variations.py` with telemetry schema 1.0; completed 438-iteration variation campaign with local Gemma 4 classifier triage archived in `TESTS-RESULTS/2026-08-20+GH-94/`; verified synthetic suites `gh94-script-serialization.sh` and `gh94-containment-invariants.sh` (7/7 PASS). → [GH-94-PROGRAMMATIC-TOOL-CALLING.md](PROJECT/3-COMPLETED/GH-94-PROGRAMMATIC-TOOL-CALLING.md) · [#94](https://github.com/HiQS-Suite/XYZ-forge/issues/94)', '2026-08-20T06:12:48Z', '2026-08-24T23:09:38Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0FWQ1S70PWTTVM7P23QR298', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '91', 'GH-91 · a build turn has nowhere to write verification output — containment kills a complete, green turn', 'Completed', '23', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-91-RELAY-SCRATCH-DIR.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/91', '- **GH-91 · a build turn has nowhere to write verification output — containment kills a complete, green turn** ✅ **CLOSED 2026-08-22 (issue closed; ledger reconciled)** — issue option 1: `.relay-scratch/` as an intrinsic write category — pre-created by `rtl_worktree_begin`, exempted in `rtl_worktree_end` (no signature check; never copied back), exempted-and-discarded in `rtl_check` (non-worktree path), and NAMED in `rtl_turn_prompt` at the point of use. New suite `test/gh91-relay-scratch.sh` 15/0 with controls (stray still exit-6, lookalike prefix not exempt, off-lane copies nothing back); containment-pinning neighbors green. Surfaced by the daybreak wave-1 re-fire after #90. rated 60/65/55/75. → [GH-91-RELAY-SCRATCH-DIR.md](PROJECT/3-COMPLETED/GH-91-RELAY-SCRATCH-DIR.md) · [#91](https://github.com/HiQS-Suite/XYZ-forge/issues/91)', '2026-08-20T15:30:27Z', '2026-08-24T23:09:38Z', '60', '65', '55', '75', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0FY5VR7R33M0WVBBCNJSTA3', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '101', 'GH-101 · Feasibility Study: Promoting Programmatic Script Runner (`script_runner.py`) into Core Relay & Consult Runtimes', 'Completed', '34', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-101-FEASIBILITY-STUDY-SCRIPT-RUNNER.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/101', '- **GH-101 · Feasibility Study: Promoting Programmatic Script Runner (`script_runner.py`) into Core Relay & Consult Runtimes** ✅ **SHIPPED 2026-08-20 (issue closed)** — evaluated and promoted programmatic tool mode across `consult.py` and `relay_drive.py` behind `--tool-mode programmatic` (default off); completed 3-test qualification ladder (Test 1 architectural review & fail-closed threat scoping; Test 2 consult dogfooding with throwaway worktree isolation, pre-created `.relay-scratch/`, and 1,935-trial paired density benchmark in `TESTS-RESULTS/2026-08-20+GH-101/`; Test 3 relay-drive PGID process cleanup stress and fail-closed sandbox checks in `test/synthetic/gh101-relay-programmatic-stress.sh`); promoted to Production-Ready (A-Grade) in `HARNESS-MODELS-REGISTRY.md`. → [GH-101-FEASIBILITY-STUDY-SCRIPT-RUNNER.md](PROJECT/3-COMPLETED/GH-101-FEASIBILITY-STUDY-SCRIPT-RUNNER.md) · [#101](https://github.com/HiQS-Suite/XYZ-forge/issues/101)', '2026-08-20T15:56:01Z', '2026-08-24T23:09:38Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0G0PGX85DBNMZC2HSJ6MF7H', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '102', 'GH-102 · Unify Telemetry Schema & Inspection Tooling Across Fuzzing and ATE', 'Completed', '36', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-102-UNIFIED-TELEMETRY-TOOLING.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/102', '- **GH-102 · Unify Telemetry Schema & Inspection Tooling Across Fuzzing and ATE** ✅ **SHIPPED 2026-08-20 (issue closed)** — standardized shared data contract (`schema_version: "1.0"`), instrumented `utils/fuzzing/fuzz-loop.sh` with argv-safe JSONL emission and sub-second millisecond timing; updated `utils/ate/scripts/run_variations.py` to triage `tokens_source` (`api_usage` vs `config_provided` vs `unsupported`); upgraded `utils/ate/scripts/checkin.py` into a universal inspector with nearest-rank percentiles and comparative side-by-side mode; verified via `test/synthetic/gh102-telemetry-schema.sh` (8/8 PASS) and archived receipts in `TESTS-RESULTS/2026-08-20+GH-102/`. → [GH-102-UNIFIED-TELEMETRY-TOOLING.md](PROJECT/3-COMPLETED/GH-102-UNIFIED-TELEMETRY-TOOLING.md) · [#102](https://github.com/HiQS-Suite/XYZ-forge/issues/102)', '2026-08-20T16:40:04Z', '2026-08-24T23:09:38Z', NULL, NULL, NULL, NULL, NULL);
