INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0GKR98K9X9FYJVH6CPSQ2BP', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '103', 'GH-103 · technical spike: RELEASES SQLite → timeline-ui ledger viewer (RELEASES dashboard view)', 'Completed', '35', '✅', NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-103-TIMELINE-LEDGER-SPIKE.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/103', '- **GH-103 · technical spike: RELEASES SQLite → timeline-ui ledger viewer (RELEASES dashboard view)** ✅ **SHIPPED 2026-08-20 (PR #104; issue closed)** — read-only exporter `utils/timeline/export_timeline.py` projects `releases.db` into timeline-ui''s `data.json` contract; viewer `utils/timeline/RELEASES.html` (header collapse caret, full-viewport liquid layout, scrollable detour lanes); `--preview` bakes the committed `RELEASES-PREVIEW.html` snapshot, auto-refreshed after every CLI write by the GH-106 hook; `--serve` answers `/data.json` live from the DB; band-aware RELEASES.md-vs-DB drift banner. Zero DB writes (SQLite `mode=ro`). Prototype for the queued #75 `releases dashboard` verb; follow-on integration tracked in #107 (Cargo). → [GH-103-TIMELINE-LEDGER-SPIKE.md](PROJECT/1-INBOX/GH-103-TIMELINE-LEDGER-SPIKE.md) · [#103](https://github.com/HiQS-Suite/XYZ-forge/issues/103)', '2026-08-20T22:13:04Z', '2026-08-24T23:09:38Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0H9CC0981F9CSAMV7BXRYXP', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '111', 'GH-111 · retire manifest FREEZE; tasks and marathons are DIALED IN to exactly one release, as a database state', 'Completed', '31', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-111-DIALED-IN.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/111', '- **GH-111 · retire manifest FREEZE; tasks and marathons are DIALED IN to exactly one release, as a database state** ✅ **SHIPPED 2026-08-21 (PR #116; issue closed)** — membership became machine-checkable instead of a sentence someone remembered to write: three states (`dialed_in`/`shipped`/`cut`), exclusivity by a partial unique index over ACTIVE membership only, a real `releases migrate` upgrade path where none existed, and BASELINES replacing what the freeze used to buy (progress against the live manifest, growth against the kickoff count). Closed #109 (the viewer asserted marathon membership the data never claimed) and #110 (`shipped` was a state nothing could write). rated 85/75/70/35. → [GH-111-DIALED-IN.md](PROJECT/3-COMPLETED/GH-111-DIALED-IN.md) · [#111](https://github.com/HiQS-Suite/XYZ-forge/issues/111)', '2026-08-21T04:31:03Z', '2026-08-24T23:09:38Z', '85', '75', '70', '35', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0H9CC0AAF9JWBSHR3679NQQ', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '108', 'GH-108 · pri/sev/appeal/effort — the canonical task rating system (calc sum + operator override)', 'Completed', '32', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-108-RATING-SYSTEM.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/108', '- **GH-108 · pri/sev/appeal/effort — the canonical task rating system (calc sum + operator override)** ✅ **SHIPPED 2026-08-21 (PR #116; issue closed)** — one scoring vocabulary for every task in the ledger, oriented so a single glance answers what should go to the front of the line: four axes 1-100 where higher is always better (effort scores cheapness), a combined 4-400 `calc` derived and never stored, and an `ovr` override that pins anything visible. Authored as `rated N/N/N/N` on a ROADMAP entry; read via `bash utils/leaderboard.sh` or LEADERBOARD.html. rated 80/50/75/40. → [GH-108-RATING-SYSTEM.md](PROJECT/3-COMPLETED/GH-108-RATING-SYSTEM.md) · [#108](https://github.com/HiQS-Suite/XYZ-forge/issues/108)', '2026-08-21T04:31:03Z', '2026-08-24T23:09:38Z', '80', '50', '75', '40', NULL);
