INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0JS79CRW0V3185JCYKJTVCK', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '124', 'GH-124 · eliminate end-of-day closeout friction — automated phase QA receipts, auto-PR creation, and clone lifecycle hygiene', 'Completed', '21', '✅', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-124-CLOSEOUT-AUTOMATION.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/124', '- **GH-124 · eliminate end-of-day closeout friction — automated phase QA receipts, auto-PR creation, and clone lifecycle hygiene** ✅ **CLOSED 2026-08-22 (issue closed; ledger reconciled)** — eliminate 50+ minutes of daily closeout friction: on-disk local gate receipts (`ci-local.sh` / `validate.sh`), driver-refreshed early drift alerts, safe manifest-bounded workspace sweep with soft quarantine, hardened `marathon-closeout.sh`, and post-gate in-flight QA attestation comments. rated 85/60/90/40. → [GH-124-CLOSEOUT-AUTOMATION.md](PROJECT/2-WORKING/GH-124-CLOSEOUT-AUTOMATION.md) · [#124](https://github.com/HiQS-Suite/XYZ-forge/issues/124)', '2026-08-21T18:27:08Z', '2026-08-24T23:09:38Z', '85', '60', '90', '40', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0KXV2WWSQVF6AQ0H4NQ7REY', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '135', 'GH-135..140 · Wave-1 follow-ups: consult preflight verdict, attempts-gate root, suite registration, twin-divergence record, SIGPIPE sweep+guard, utcnow swap', 'Completed', '29', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-135-CONSULT-AGY-PREFLIGHT.md', NULL, '- **GH-135..140 · Wave-1 follow-ups: consult preflight verdict, attempts-gate root, suite registration, twin-divergence record, SIGPIPE sweep+guard, utcnow swap** ✅ **SHIPPED 2026-08-22 (PR #145, squash 9c07f0cc; issues closed)** — six follow-up issues fixed on one branch: consult.py routes non-zero whoami exits through the shared verdict (#135); TICK_REPO_ROOT resolves ahead of the lane-attempt gate with the NOTE still after the lock (#136); the Wave-1 suites + the gh139 guard registered in TESTS (#137); the post-#129 twin divergence pinned (#138); 369 of 482 pipe-into-`grep -q` sites swept to capture-then-match with a ratchet guard over a ~120-entry shrinking baseline (#139 — the sweep''s own gate run caught and repaired three negation-inversion conversions and signal-triage''s escaped-quote mangle, each verified by suite re-run); the three utcnow() sites swapped timezone-aware (#140). Full gate 237/237; relay QA by agy returned VERDICT: PASS. → [GH-135-CONSULT-AGY-PREFLIGHT.md](PROJECT/3-COMPLETED/GH-135-CONSULT-AGY-PREFLIGHT.md) · [GH-136-ATTEMPTS-GATE-ROOT.md](PROJECT/3-COMPLETED/GH-136-ATTEMPTS-GATE-ROOT.md) · [GH-137-SUITE-REGISTRATION.md](PROJECT/3-COMPLETED/GH-137-SUITE-REGISTRATION.md) · [GH-138-TWIN-DIVERGENCE-RECORD.md](PROJECT/3-COMPLETED/GH-138-TWIN-DIVERGENCE-RECORD.md) · [GH-139-SIGPIPE-SWEEP-GUARD.md](PROJECT/3-COMPLETED/GH-139-SIGPIPE-SWEEP-GUARD.md) · [GH-140-UTCNOW-DEPRECATION.md](PROJECT/3-COMPLETED/GH-140-UTCNOW-DEPRECATION.md)', '2026-08-22T05:07:05Z', '2026-08-24T23:09:38Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0KXV2WW44KYJFGMZJEMD8G8', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', NULL, '#129/#130/#131 · Wave 1 of the Harness Driver & Relay Seam Hardening marathon — three preflighted driver/relay fixes', 'Completed', '30', '✅', NULL, NULL, NULL, NULL, 'https://github.com/HiQS-Suite/XYZ-forge/issues/129', '- **#129/#130/#131 · Wave 1 of the Harness Driver & Relay Seam Hardening marathon — three preflighted driver/relay fixes** ✅ **SHIPPED 2026-08-22 (PR #134, squash d92236cb; issues closed)** — relay-drive self-resolves TICK_REPO_ROOT via resolve_turn_root when unset and replaces the misleading "token missing" with a diagnostic naming the resolved root and searched event dir, every escalation pinned at exit 4; the agy auth preflight classifies usage/CLI-syntax errors as unverifiable (non-blocking) while credentials errors stay exit 5; marathon-drive''s phase write-set (RELAY.md/ESCALATION.md) commits route to `phase_commit_root` — the repo containing phase_dir — making `--target-root` + target `--phases-dir` runnable for the first time. Three suites (33 assertions) with recorded pre-fix negative controls; full gate 233/233; first-gate run caught the gh376 twin-parity ordering defect (NOTE must print after the lock refusal). Follow-ups filed as #135-#140. → [#129](https://github.com/HiQS-Suite/XYZ-forge/issues/129) · [#130](https://github.com/HiQS-Suite/XYZ-forge/issues/130) · [#131](https://github.com/HiQS-Suite/XYZ-forge/issues/131)', '2026-08-22T05:07:05Z', '2026-08-24T23:09:38Z', NULL, NULL, NULL, NULL, NULL);
