INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0M5V0KCZE5D0T655AV5E3J8', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '141', 'GH-141 · make Fuzzing and ATE actually useful — Phases 1, 2, 4, 5 (+ #142 prerequisite); Phase 3 deferred pending #143''s incidence comparison', 'In progress', '5', '🚧', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-141-FUZZ-ATE-UTILITY.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/141', '- **GH-141 · make Fuzzing and ATE actually useful — Phases 1, 2, 4, 5 (+ #142 prerequisite); Phase 3 deferred pending #143''s incidence comparison** 🚧 **active 2026-08-22 on branch `gh141-fuzz-ate-utility`** — one selector owns the synthetic suites (validate.sh `--list` consumed by fuzz-loop, all 14 synthetic suites registered, divergence regression), telemetry de-aliased (nested `classification.status` removed; severity/likely_cause become derived signal from documented exit classes and output classes, consumers updated in-phase), the ATE chain fails loudly (#142''s exit-code contract: 0 filed · 3 no-records · 1 gh-failed, propagated through run_variations) with a hermetic stub-`gh` chain regression, and ATE decoupled from Aider (neutral default labels, `expects_edits` grid key fixing #146''s 17 false-HIGH no_edit verdicts, turn-shim grid declared, SKILL.md generalized). Phase 3 (generative boundary fuzzing) deliberately NOT scheduled — #143''s counted comparison picks the target first, per the issue''s own recommendation. rated 80/65/85/55. → [GH-141-FUZZ-ATE-UTILITY.md](PROJECT/2-WORKING/GH-141-FUZZ-ATE-UTILITY.md) · [#141](https://github.com/HiQS-Suite/XYZ-forge/issues/141) · [#142](https://github.com/HiQS-Suite/XYZ-forge/issues/142) · [#146](https://github.com/HiQS-Suite/XYZ-forge/issues/146)', '2026-08-22T07:26:52Z', '2026-08-24T23:09:38Z', '80', '65', '85', '55', NULL);
