INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0R1R2MGX6WRH12BC42ZZFTH', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '195', 'GH-195 · marathon-root-audit''s blind spot: a direct `python3 marathon_drive.py` call', 'Completed', '15', '✅', NULL, NULL, NULL, 'PROJECT/3-COMPLETED/GH-195-MARATHON-ROOT-AUDIT-BLIND-SPOT.md', NULL, '- **GH-195 · marathon-root-audit''s blind spot: a direct `python3 marathon_drive.py` call** ✅ **SHIPPED 2026-08-23 (in PR #194)** — GH-115''s own new test committed a live transcript onto the real clone on every `validate.sh` run because `marathon-root-audit.sh` only audits `bash <driver>.sh` invocations, never a direct Python call; same defect class as GH-401, reopened via a different invocation shape. Root-caused via direct instrumentation after ~2.5h of correctly-reasoned-but-wrong process-hunting. rated 60/40/50/20. → [GH-195-MARATHON-ROOT-AUDIT-BLIND-SPOT.md](PROJECT/3-COMPLETED/GH-195-MARATHON-ROOT-AUDIT-BLIND-SPOT.md) · [#195](https://github.com/HiQS-Labs/XYZ-forge/issues/195)', '2026-08-23T19:32:19Z', '2026-08-24T23:09:38Z', '60', '40', '50', '20', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0RWH5YT8VSNS858ZQSZ59MC', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '197', 'GH-197 · two-tier xyz-vendor.sh: Tier 1 core-harness default, Tier 2 opt-in RELEASES overlay + onboarding SOP (GH-105 follow-up)', 'Completed', '5', '✅', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-197-VENDOR-TIER-SPLIT.md', 'https://github.com/HiQS-Suite/XYZ-forge/issues/197', '- **GH-197 · two-tier xyz-vendor.sh: Tier 1 core-harness default, Tier 2 opt-in RELEASES overlay + onboarding SOP (GH-105 follow-up)** ✅ **SHIPPED 2026-08-24 (PR #210)** — deny-list tier split in `materialize_vendor()` (`--with-releases`), sticky Tier 2 auto-detect via `releases.db` at target root for the 9 vendored repos, and `xyz-releases-onboard.sh` mechanizing the LTVera-Pandas `ad0d816` onboarding (import, gitignore carve-out, banner, MIG- reconcile with shared-tracking-URL refusal, no auto-commit). rated 80/55/65/50. → [GH-197-VENDOR-TIER-SPLIT.md](PROJECT/2-WORKING/GH-197-VENDOR-TIER-SPLIT.md) · [#197](https://github.com/HiQS-Suite/XYZ-forge/issues/197)', '2026-08-24T03:20:24Z', '2026-08-24T23:09:38Z', '80', '55', '65', '50', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0S8827CZ9NQR68YWK62DNR8', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '201', 'GH-201 · Gen 3.5 follow-ups — remaining ATE hardening arc (tasks 3–8b of #174)', 'In progress', '4', '🚧', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-201-GEN35-FOLLOWUPS.md', NULL, '- **GH-201 · Gen 3.5 follow-ups — remaining ATE hardening arc (tasks 3–8b of #174)** 🚧 **active 2026-08-24 for release 0.9.0 "Cargo" (draft)** — deterministic Phase 1–3 fixes (A1–A9/A11), the remaining data-path wiring (explorer→repro-builder + E2E rewrite), explorer sharpening + per-probe zero-mutation oracle, gated Phase 4 autonomy (full-clone dispatch, GH-221 predicates, budget governor), the five-canary calibration hour, and the Gemma Tier-1 sensor (Part H, advisory-until-calibrated); healer safety rides separately as #182 on Bulkhead. rated 80/70/80/45. → [GH-201-GEN35-FOLLOWUPS.md](PROJECT/2-WORKING/GH-201-GEN35-FOLLOWUPS.md) · [#201](https://github.com/HiQS-Labs/XYZ-forge/issues/201)', '2026-08-24T06:45:08Z', '2026-08-24T23:09:38Z', '80', '70', '80', '45', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0S8827CVPCVRMWD3PH4E5YZ', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '193', 'GH-193 · AgentChorus Gen 2', 'Completed', '6', '🚧', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-193-AGENTCHORUS-GEN2.md', NULL, '- **GH-193 · AgentChorus Gen 2 ** ✅ **SHIPPED 2026-08-24 (PR #210)** — telemetry, decision-quality metrics, measurable experiments (Agent2Agent renamed)** 🚧 **active 2026-08-24 for release 0.7.3 "Bulkhead" (#179); Phases 0-1 SHIPPED (PR #196, PR #200 2026-08-24 — telemetry + registry + outcome + audit + data policy; suite 142/142); pilot window running; phases 2-3 continue** — make discussion decisions measurable: metadata-only telemetry with a structural no-content allowlist, a store-level aggregate registry, per-model outcome attribution, supersession/lifecycle verbs, verify-citations with ref pinning, and experiment flags (steelman, stance prior) gated on the ≥10-discussion pilot corpus. rated 75/70/85/50. → [GH-193-AGENTCHORUS-GEN2.md](PROJECT/2-WORKING/GH-193-AGENTCHORUS-GEN2.md) · [#193](https://github.com/HiQS-Labs/XYZ-forge/issues/193)', '2026-08-24T06:45:08Z', '2026-08-24T23:09:38Z', '75', '70', '85', '50', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0T6MXXT5RJZ7SA9523MYSBT', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '202', 'GH-202 · wave_reconcile aborts on marathon-plan exit 5 (items held) and promotes capture docs for OPEN issues', 'Completed', '4', '✅', NULL, NULL, NULL, 'PROJECT/2-WORKING/GH-202-WAVE-RECONCILER-STATE.md', NULL, '- **GH-202 · wave_reconcile aborts on marathon-plan exit 5 (items held) and promotes capture docs for OPEN issues** ✅ **SHIPPED 2026-08-24 (PR #210)** — hotfix, the reconciler sits on every merge critical path** — tolerate the items-held planning state (log + continue), and consult the linked issue''s open/closed state before promoting a doc: OPEN keeps the doc active with recorded merge evidence (idempotent), unknown state promotes as before (offline-manifest backward compat). rated 85/65/85/70. → [GH-202-WAVE-RECONCILER-STATE.md](PROJECT/2-WORKING/GH-202-WAVE-RECONCILER-STATE.md) · [#202](https://github.com/HiQS-Labs/XYZ-forge/issues/202)', '2026-08-24T15:36:27Z', '2026-08-24T23:09:38Z', '85', '65', '85', '70', NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0V0JQD8KPV31HM2GH68WRTB', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '221', 'GH-221 — agy-turn.sh auth pre-flight breaks on agy CLI >=1.1.19 — whoami subcommand removed', 'Queue / parked intake', '2', NULL, NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-221-AGY-WHOAMI-PREFLIGHT.md', NULL, '- **GH-221 — agy-turn.sh auth pre-flight breaks on agy CLI >=1.1.19 — whoami subcommand removed** (2026-08-24) - `whoami` no longer exists in agy CLI >=1.1.19, so the auth pre-flight hard-fails every headless agy-turn.sh run and misreports it as a login problem. Bug filed via /file-xyz-bug from `aegis-sleuth-slack-bot`. Issue [#221](https://github.com/HiQS-Labs/XYZ-forge/issues/221). -> [PROJECT/1-INBOX/GH-221-AGY-WHOAMI-PREFLIGHT.md](PROJECT/1-INBOX/GH-221-AGY-WHOAMI-PREFLIGHT.md)', '2026-08-24T23:09:38Z', '2026-08-24T23:36:03Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0V0JQD8T7VH32KB1ZX97PD3', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '215', 'GH-215 — wave_reconcile.py and roadmap-dashboard.sh hardcode pre-vendoring path depth', 'Queue / parked intake', '3', NULL, NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-215-RECONCILER-VENDOR-PATHS.md', NULL, '- **GH-215 — wave_reconcile.py and roadmap-dashboard.sh hardcode pre-vendoring path depth** (2026-08-24) - both assume a bare `utils/` at repo root; under vendored `.xyz/` they die on missing files / ENOENT. Fixed locally in the reporting repo, not yet upstream. Bug filed via /file-xyz-bug from `LTVera-Pandas`. Issue [#215](https://github.com/HiQS-Labs/XYZ-forge/issues/215). -> [PROJECT/1-INBOX/GH-215-RECONCILER-VENDOR-PATHS.md](PROJECT/1-INBOX/GH-215-RECONCILER-VENDOR-PATHS.md)', '2026-08-24T23:09:38Z', '2026-08-24T23:36:03Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0V0JQD8MQPVYZ6KBTD1A1C9', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '216', 'GH-216 — marathon-plan.sh ledger parser rejects link-style ROADMAP.md bullets', 'Queue / parked intake', '4', NULL, NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-216-LEDGER-BULLET-FORMAT.md', NULL, '- **GH-216 — marathon-plan.sh ledger parser rejects link-style ROADMAP.md bullets** (2026-08-24) - reconciler never completes in a repo whose ROADMAP.md uses `- [Title](path) — ...` bullets; exit 3 every time. Open design question, not patched. Bug filed via /file-xyz-bug from `LTVera-Pandas`. Issue [#216](https://github.com/HiQS-Labs/XYZ-forge/issues/216). -> [PROJECT/1-INBOX/GH-216-LEDGER-BULLET-FORMAT.md](PROJECT/1-INBOX/GH-216-LEDGER-BULLET-FORMAT.md)', '2026-08-24T23:09:38Z', '2026-08-24T23:36:03Z', NULL, NULL, NULL, NULL, NULL);
INSERT INTO roadmap_items(global_id, repo_gid, gh_number, title, section, position, status_marker, complexity, risk, effort, doc_path, issue_url, raw_text, first_seen, updated_at, rating_pri, rating_sev, rating_appeal, rating_effort, rating_ovr) VALUES('rmi-01M0V232SZZQ6ATM49ADY37H2S', 'repo-01M0BTBRJ0PZF51EK6PCRJ20FS', '222', 'GH-222 — releases update cannot re-point a release''s tracking issue', 'Queue / parked intake', '1', NULL, NULL, NULL, NULL, 'PROJECT/1-INBOX/GH-222-RELEASES-TRACKING-REPOINT.md', NULL, '- **GH-222 — releases update cannot re-point a release''s tracking issue** (2026-08-24) - a superseded tracking umbrella (LTVera-Pandas #225→#236) leaves the ledger permanently pointing at a closed issue; `releases update` has no `--tracking-issue` and `reconcile` only fills TMP refs. Dialed into 0.7.3 Bulkhead by operator 2026-08-24. Issue [#222](https://github.com/HiQS-Labs/XYZ-forge/issues/222). -> [PROJECT/1-INBOX/GH-222-RELEASES-TRACKING-REPOINT.md](PROJECT/1-INBOX/GH-222-RELEASES-TRACKING-REPOINT.md)', '2026-08-24T23:36:03Z', '2026-08-24T23:36:03Z', NULL, NULL, NULL, NULL, NULL);
